// import type { ComponentStyleVariantConfig, Theme } from "@types";
import type { AIPromptProps } from "./ai-prompt.types";

import { type CSSObject, keyframes } from "@emotion/react";
import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import { ButtonClasses } from "@components/button";
import { useMemo } from "react";

// Make sure component name matches its type in the ThemeComponentVariants
const componentName = "AIPrompt";

const shimmerSlide = keyframes`
  0% {
    background-position: 200% center, 0 0;
  }
  100% {
    background-position: -200% center, 0 0;
  }
`;

// Generate child element class names for the component, should match available style slots
export const AIPromptClasses = {
  root: "exp-textura_ai_prompt",
  input: "exp-textura_ai_prompt_input",
  status: "exp-textura_ai_prompt_status",
  statusLabel: "exp-textura_ai_prompt_status_label",
  statusLabelIcon: "exp-textura_ai_prompt_status_label_icon",
  statusActions: "exp-textura_ai_prompt_status_actions",
  button: "exp-textura_ai_prompt_button",
  footer: "exp-textura_ai_prompt_footer",
  footerLeading: "exp-textura_ai_prompt_footer_leading",
  footerTrailing: "exp-textura_ai_prompt_footer_trailing",
  context: "exp-textura_ai_prompt_context",
  taskBar: "exp-textura_ai_prompt_task_bar",
  taskBarPopup: "exp-textura_ai_prompt_task_bar_popup",
  taskBarHeader: "exp-textura_ai_prompt_task_bar_header",
  taskBarContent: "exp-textura_ai_prompt_task_bar_content",
  taskBarContentInner: "exp-textura_ai_prompt_task_bar_content_inner",
};

// Helper hook to get style slots
const useAIPromptStyleSlots = (props: AIPromptProps) => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  return useMemo(
    () =>
      getStyleSlots<AIPromptProps["styleSlots"]>(componentName, theme!, variant, styleSlotsProp),
    [theme, variant, styleSlotsProp],
  );
};

// --- StyledAIPrompt ---

const generatePromptStyles = (props: AIPromptProps): CSSObject => {
  const { currentTheme: theme } = props;
  if (!theme) return {};
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useAIPromptStyleSlots(props);

  return {
    display: "flex",
    flexDirection: "column",
    width: "100%",
    backgroundColor: theme.color.background.default,
    border: `${theme.border.width.sm} solid ${theme.color.border.default}`,
    borderRadius: theme.toRem(8),
    [`.${AIPromptClasses.taskBar} + &`]: {
      borderTopLeftRadius: 0,
      borderTopRightRadius: 0,
      borderTop: 0,
    },
    "&:hover:not(:focus-within):not([data-thinking='true'])": {
      borderColor: theme.color.border.strong,
    },
    "&:focus-within:not([data-thinking='true'])": {
      borderColor: theme.color.focus.default,
    },
    "&[data-thinking='true']": {
      border: "1px solid transparent",
      borderRadius: theme.toRem(8),
      position: "relative",
      zIndex: 0,
      backgroundColor: "transparent",
      backgroundClip: "border-box",

      // Layer 1: The "Glow" + "Shimmer" (Bottom)
      "&::before": {
        content: '""',
        position: "absolute",
        inset: -2,
        zIndex: -1,
        borderRadius: `calc(${theme.toRem(8)} + 2px)`,
        backgroundImage: `
          linear-gradient(90deg, transparent 0%, transparent 35%, rgba(255,255,255,0.8) 50%, transparent 65%, transparent 100%),
          linear-gradient(90deg, ${theme.color.brand.primary.purple}, ${theme.color.brand.tertiary.pink100})
        `,
        backgroundSize: "200% 100%, 100% 100%",
        animation: `${shimmerSlide} 3s linear infinite`,
        filter: "blur(1px)",
      },

      // Layer 2: The "White Background" (Middle)
      "&::after": {
        content: '""',
        position: "absolute",
        inset: 0,
        zIndex: -1,
        borderRadius: "inherit",
        backgroundColor: theme.color.background.default,
        backgroundClip: "padding-box",
      },
    },

    [`.${AIPromptClasses.context}`]: {
      width: "100%",
      ...styleSlots?.context,
    },
    [`.${AIPromptClasses.input}`]: {
      width: "100%",
      border: "none",
      outline: "none",
      resize: "none",
      backgroundColor: "transparent",
      color: theme.color.content.default,
      padding: `${theme.toRem(theme.spacing[8])} ${theme.toRem(theme.spacing[12])}`,
      minHeight: theme.toRem(76),
      ...theme.typography.body.md,
      "&::placeholder": {
        color: theme.color.content.weak,
      },
      "&:focus, &:focus-visible": {
        outline: "none",
        boxShadow: "none",
        border: "none",
      },
      ...styleSlots?.input,
    },
    [`.${AIPromptClasses.status}`]: {
      display: "flex",
      alignItems: "center",
      justifyContent: "space-between",
      gap: theme.toRem(theme.spacing[8]),
      padding: `${theme.toRem(theme.spacing[8])} ${theme.toRem(theme.spacing[12])}`,
      minHeight: theme.toRem(48),
      color: theme.color.content.weak,
      ...theme.typography.body.md,
      ...styleSlots?.status,
    },
    [`.${AIPromptClasses.statusLabel}`]: {
      display: "flex",
      alignItems: "center",
      gap: theme.toRem(theme.spacing[8]),
      svg: {
        fontSize: theme.toRem(16),
        ...styleSlots?.statusLabelIcon,
      },
      ...styleSlots?.statusLabel,
    },
    [`.${AIPromptClasses.statusActions}`]: {
      display: "flex",
      alignItems: "center",
      gap: theme.toRem(theme.spacing[8]),
      ...styleSlots?.statusActions,
    },
    [`.${AIPromptClasses.button}`]: {
      width: theme.toRem(32),
      height: theme.toRem(32),
      minWidth: theme.toRem(32),
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      [`&.${ButtonClasses.root}`]: {
        padding: 0,
        fontSize: theme.toRem(16),
        width: theme.toRem(32),
      },
      ...styleSlots?.button,
    },
    [`.${AIPromptClasses.footer}`]: {
      display: "flex",
      alignItems: "center",
      justifyContent: "space-between",
      padding: theme.toRem(theme.spacing[8]),
      [`* + &`]: {
        paddingTop: 0,
      },
      ...styleSlots?.footer,
    },
    [`.${AIPromptClasses.footerLeading}`]: {
      display: "flex",
      alignItems: "center",
      gap: theme.toRem(theme.spacing[4]),
      minWidth: 0,
      maxWidth: `calc(100% - ${theme.toRem(theme.spacing[64])})`,
      flex: 1,
      ...styleSlots?.footerLeading,
    },
    [`.${AIPromptClasses.footerTrailing}`]: {
      display: "flex",
      alignItems: "center",
      gap: theme.toRem(theme.spacing[8]),
      ...styleSlots?.footerTrailing,
    },

    button: {
      flexShrink: 0,
    },

    ...styleSlots?.root,
  };
};

const excludedPromptDOMProps = [...getExcludedDOMProps(), "thinking"];

export const StyledAIPrompt = styled("div", {
  shouldForwardProp: (prop) => !excludedPromptDOMProps.includes(prop),
})<AIPromptProps>((props) => generatePromptStyles(props));

// --- StyledAIPromptTaskBar ---

const generateTaskBarStyles = (props: AIPromptProps): CSSObject => {
  const { currentTheme: theme } = props;
  if (!theme) return {};
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useAIPromptStyleSlots(props);

  return {
    position: "relative",
    width: "100%",
    zIndex: 0,
    height: theme.toRem(36),
    marginBottom: theme.toRem(-8),
    marginTop: theme.toRem(8),

    [`.${AIPromptClasses.taskBarPopup}`]: {
      display: "flex",
      flexDirection: "column",
      position: "absolute",
      bottom: 0,
      left: 0,
      right: 0,
      backgroundColor: theme.color.background.strong,
      padding: `${theme.toRem(theme.spacing[8])} ${theme.toRem(theme.spacing[8])} ${theme.toRem(16)}`,
      borderTopLeftRadius: theme.toRem(theme.spacing[8]),
      borderTopRightRadius: theme.toRem(theme.spacing[8]),
      ...styleSlots?.taskBarPopup,
    },

    // Header
    [`.${AIPromptClasses.taskBarHeader}`]: {
      display: "flex",
      alignItems: "center",
      gap: theme.toRem(theme.spacing[8]),
      cursor: "pointer",
      userSelect: "none",
      fontSize: theme.toRem(14),
      fontWeight: 500,
      paddingBottom: 0,
      transition: "padding-bottom 0.2s ease-in-out",
      flexShrink: 0, // Prevent header from shrinking

      svg: {
        transition: "transform 0.2s ease-in-out",
        transform: "rotate(0deg)",
        ":dir(rtl)": {
          transform: "rotate(180deg)",
        },
        ...styleSlots?.taskBarHeaderIcon,
      },
      "&[aria-expanded='true']": {
        paddingBottom: theme.toRem(theme.spacing[8]),
        svg: {
          transform: "rotate(90deg)",
          ":dir(rtl)": {
            transform: "rotate(90deg)",
          },
        },
        ...styleSlots?.taskBarHeaderExpanded,
      },

      ...styleSlots?.taskBarHeader,
    },

    // Content Wrapper (Grid for Height Transition)
    [`.${AIPromptClasses.taskBarContent}`]: {
      display: "grid",
      gridTemplateRows: "0fr",
      overflow: "hidden",
      transition: "grid-template-rows 0.2s ease-out",

      "&[data-expanded='true']": {
        gridTemplateRows: "1fr",
        ...styleSlots?.taskBarContentExpanded,
      },

      ...styleSlots?.taskBarContent,
    },

    // Content Inner (Visibility & Layout)
    [`.${AIPromptClasses.taskBarContentInner}`]: {
      minHeight: 0,
      paddingBottom: 0,
      transition: "padding-bottom 0.2s ease-out",

      ...styleSlots?.taskBarContentInner,
    },

    ...styleSlots?.taskBar,
  };
};

const excludedTaskBarDOMProps = [...getExcludedDOMProps(), "expanded"];

export const StyledAIPromptTaskBar = styled("div", {
  shouldForwardProp: (prop) => !excludedTaskBarDOMProps.includes(prop),
})<AIPromptProps>((props) => generateTaskBarStyles(props));
